using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using Gunt.ControlCenter.Models;using Gunt.ControlCenter.Services;
namespace Gunt.ControlCenter.Views {
 public sealed partial class MainWindow {
  void BuildCommandsPage(){Text("GUNT 동작과 프로젝트 도구만 검색합니다. Windows 검색·Flow Launcher의 Alt+Space는 변경하지 않습니다.",true);foreach(var field in vm.Fields)AddField(field);var keyStatus=vm.Service.State("developer-hotkey");Text("상단 바 등록 상태: "+DesktopService.S(keyStatus,"Status","다음 상단 바 시작 때 등록"),true);var a=Actions();var search=new TextBox{Margin=new Thickness(0,6,0,8)};AutomationProperties.SetName(search,"명령 관리 검색");content.Children.Add(search);commandList=DataList("등록된 GUNT 명령",220);content.Children.Add(commandList);Action filter=()=>{commandList.ItemsSource=vm.Service.SearchCommands(search.Text);if(commandList.Items.Count>0)commandList.SelectedIndex=0;};search.TextChanged+=delegate{filter();};filter();a=Actions();Action(a,"명령 즐겨찾기 전환",()=>{var c=Dispatcher.Invoke(new Func<CommandEntry>(()=>commandList.SelectedItem as CommandEntry));if(c==null)throw new ArgumentException("명령을 선택하세요.");vm.Service.FavoriteCommand(c.Id);Dispatcher.Invoke(filter);return "명령 즐겨찾기를 저장했습니다.";});var alias=EditBox(content,"추가할 별칭 (내장 cx·oc·dev와 중복 불가)","");Action(a,"선택 명령 별칭 추가",()=>{var c=Dispatcher.Invoke(new Func<CommandEntry>(()=>commandList.SelectedItem as CommandEntry));string text=Dispatcher.Invoke(new Func<string>(()=>alias.Text));if(c==null)throw new ArgumentException("명령을 선택하세요.");vm.Service.SaveAlias(text,c.Id);return "충돌 없이 별칭을 추가했습니다.";});var aliases=DataList("사용자 명령 별칭",90);aliases.ItemsSource=vm.Service.CommandsConfig().Aliases.Select(p=>new ChoiceOption(p.Key,p.Key+" → "+p.Value)).ToArray();content.Children.Add(aliases);Action(a,"선택 별칭 삭제",()=>{var selected=Dispatcher.Invoke(new Func<ChoiceOption>(()=>aliases.SelectedItem as ChoiceOption));if(selected==null)throw new ArgumentException("별칭을 선택하세요.");vm.Service.DeleteAlias(selected.Key);Dispatcher.Invoke((Action)(()=>Show("commands")));return "사용자 별칭을 삭제했습니다.";});var open=new Button{Content="명령 팔레트 열기"};open.Click+=delegate{OpenCommandPalette();};a.Children.Add(open);}
 }
}
